mapper.select:
SELECT S.ID AS "subjectId",UVA.VIDEO_ID as "videoId", UVA.TYPE as "type", UVA.STAR_VALUE as "starValue", UVA.VALUE as "value" FROM GC_SUBJECT S LEFT JOIN GC_SUBJECT S0 ON S0.FID=S.ID LEFT JOIN GC_VIDEO V ON V.SUB_ID = S0.ID LEFT JOIN GC_USER_VIDEO_ACTION UVA ON UVA.VIDEO_ID = V.ID
AND UVA.VIDEO_ID = #{videoId}
AND UVA.TYPE = #{type}
AND UVA.VIDEO_ID IN
#{videoId}
AND S.ID IN
#{id}

SELECT S.ID AS "subjectId",COUNT(uva."user_id") as "subjectStarUsers", ROUND(AVG(UVA.STAR_VALUE),1) as "subjectStarAvg" FROM GC_SUBJECT S LEFT JOIN GC_SUBJECT S0 ON S0.FID=S.ID LEFT JOIN GC_VIDEO V ON V.SUB_ID = S0.ID LEFT JOIN GC_USER_VIDEO_ACTION UVA ON UVA.VIDEO_ID = V.ID WHERE UVA.type=3
AND S.ID IN
#{id}
AND UVA.VIDEO_ID IN
#{videoId}
GROUP BY s.id

SELECT UVA.sub_id AS "subjectId",COUNT(uva."user_id") as "subjectStarUsers", ROUND(AVG(UVA.STAR_VALUE),1) as "subjectStarAvg" FROM GC_USER_VIDEO_ACTION UVA left join gc_subject s on s.id=UVA.sub_id WHERE UVA.type=4 and s.id in
#{id}
GROUP BY s.id

SELECT S.ID AS "subjectId",COUNT(uva."user_id") as "subjectStarUsers", AVG(UVA.STAR_VALUE) as "subjectStarAvg" FROM GC_SUBJECT S LEFT JOIN GC_SUBJECT S0 ON S0.FID=S.ID LEFT JOIN GC_VIDEO V ON V.SUB_ID = S0.ID LEFT JOIN GC_USER_VIDEO_ACTION UVA ON UVA.VIDEO_ID = V.ID WHERE UVA.type=3 AND S.id=#{subId}
AND UVA.VIDEO_ID IN
#{videoId}
GROUP BY S.id

select count(1) as videoLikeNum,video_id as videoId from gc_user_video_action where type =1 and video_id in
#{videoId}
group by video_id

select ac.*,info.avatar_file_id as userAvatarFileId,info.last_name as userLastName,info.first_name as userFirstName from gc_user_video_action ac left join gc_user us on us.id = ac.user_id left join gc_user_info info on info.id = us.info_id where ac.sub_id=#{subId} and type=#{starType}
AND ac.star_value=#{starFilter}
order by ac.star_value desc
order by ac.star_value asc
order by ac.update_time desc

select count(1) as videoLikeNum,file_id as videoId from gc_user_video_action where type =1 and file_id in
#{fileId}
group by file_id
